"""Lizard disease dictionary and analysis module.

This module defines a comprehensive list of diseases commonly seen in
captive and wild lizards (Lacertilia / Sauria) including bearded dragons,
leopard geckos, chameleons, iguanas, monitors, and other popular species.
It exposes an ``analyze_symptoms`` function that leverages the generic
species helper to produce differential diagnosis results.

The information provided here is for educational purposes only and should
not replace professional veterinary diagnosis and treatment.
"""

from __future__ import annotations

from typing import Any, Dict, List

from . import prevalence_data
from .helpers import ADVICE, analyze_symptoms_generic, enrich_diseases

