    {
        "name": "Periodontal Disease",
        "name_ja": "歯周病",
        "symptoms": {"swollen_gums", "mouth_lesions", "anorexia", "facial_swelling"},
        "description": "未治療の場合に生命を脅かす可能性のある肺の細菌・真菌感染症です。",
        "description_ja": "特にアクロドント種（フトアゴヒゲトカゲ、カメレオン）で歯の周囲組織に炎症・感染が起こる疾患です。",
        "urgency": "moderate",
        "recommended_tests": ["oral_exam", "radiographs", "culture_sensitivity"],
        "causes": "Inflammation and infection of the tissues surrounding the teeth, especially in acrodont species (bearded dragons, chameleons).",
        "causes_ja": "Lizardにおける歯周病の原因: 特にアクロドント種（フトアゴヒゲトカゲ、カメレオン）で歯の周囲組織に炎症・感染が起こる疾患です。",
        "pathophysiology": "Periodontal Disease is a dental/oral condition in Lizard. Inflammation and infection of the tissues surrounding the teeth, especially in acrodont species (bearded dragons, chameleons). Dental pathology in this species involves disruption of normal tooth structure, alignment, or supporting tissues. Abnormal tooth growth or wear patterns can lead to malocclusion, root elongation, and periapical abscess formation. Periodontal disease involves bacterial biofilm accumulation, gingival inflammation, and progressive loss of periodontal attachment. Pain from dental disease often manifests as reduced food intake, selective eating, weight loss, and ptyalism.",
        "pathophysiology_ja": "歯周病はLizardにおける歯科・口腔疾患である。歯の構造、配列、または支持組織の正常な機能が障害される。異常な歯の成長・摩耗パターンは不正咬合、歯根伸長、根尖膿瘍形成を引き起こしうる。歯周病は細菌バイオフィルムの蓄積、歯肉炎症、歯周付着の進行性喪失を伴う。歯科疾患による疼痛は食欲低下、選択的摂食、体重減少、流涎として現れることが多い。",
        "treatment": "Treatment of periodontal disease in lizard requires dental examination under sedation or anesthesia for thorough assessment. Malocclusion may require tooth trimming, burring, or extraction depending on species and severity. Periapical abscesses require drainage, debridement, and systemic antibiotics. Periodontal disease treatment includes scaling, polishing, and extraction of severely affected teeth. Pain management with species-appropriate analgesics is essential. Dietary modifications support recovery and prevent recurrence.",
        "treatment_ja": "Lizardにおける歯周病の治療には鎮静または麻酔下での歯科検査が必要である。不正咬合は種と重症度に応じて歯のトリミング、研磨、抜歯が必要となる。根尖膿瘍には排膿、デブリードマン、全身性抗菌薬が必要である。歯周病治療にはスケーリング、研磨、重度罹患歯の抜歯を含む。種に適した鎮痛薬による疼痛管理が不可欠である。食事の調整により回復を促進し再発を予防する。",
        "prevention": "歯周病の予防には自然な歯の摩耗を促進する適切な咀嚼材と食事、定期的な歯科検査、発生しつつある不正咬合の早期矯正、種に適した食物繊維の提供が含まれる。",
        "prevention_ja": "歯周病の予防には自然な歯の摩耗を促進する適切な咀嚼材と食事、定期的な歯科検査、発生しつつある不正咬合の早期矯正、種に適した食物繊維の提供が含まれる。",
        "prognosis": "",
        "prognosis_ja": "歯周病の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
