    {
        "name": "Temporal Gland Disorder (Iguanas)",
        "name_ja": "側頭腺障害（イグアナ）",
        "symptoms": {"head_swelling", "facial_swelling", "lethargy", "anorexia"},
        "description": "口内炎や咬傷に続発する骨の細菌感染症です。",
        "description_ja": "イグアナの鼓室下板・側頭腺の過形成または感染です。",
        "urgency": "moderate",
        "recommended_tests": ["physical_exam", "fine_needle_aspirate", "radiographs"],
        "causes": "Caused by infection or obstruction of the subtympanic shield (temporal gland) in iguanas, often secondary to vitamin A deficiency or bacterial infection.",
        "causes_ja": "Lizardにおける側頭腺障害（イグアナ）の原因: イグアナの鼓室下板・側頭腺の過形成または感染です。",
        "pathophysiology": "骨髄炎（Lizard）はLizardにおける整形外科・筋骨格系疾患である。骨、関節、または支持軟部組織の構造的損傷、変性変化、発達異常を伴う。軟骨変性、軟骨下骨リモデリング、滑膜炎が関節疾患を特徴づける。腱・靭帯損傷は機械的安定性を障害する。疼痛、跛行、運動性低下がQOLに大きく影響する特徴的な臨床徴候である。",
        "pathophysiology_ja": "側頭腺障害（イグアナ）はLizardにおける血液・全身性疾患である。正常な血球産生、機能、または破壊の障害を伴う病態生理を有する。骨髄障害、脾臓隔離、消費性凝固障害、末梢破壊機構が関与しうる。酸素運搬能の低下（貧血）、止血不全（血小板減少症、DIC）、異常な細胞増殖（多血症）により組織灌流と臓器機能が障害される。肝、腎、心血管系の二次的臓器障害が発生しうる。",
        "treatment": "Lizardにおける骨髄炎（Lizard）の治療は原因への対処、適切な支持療法、臨床徴候の管理を行う。種に適した薬物療法、食事の最適化、環境調整が主要な治療要素である。定期的なフォローアップにより治療効果を確認し用量調整を行う。",
        "treatment_ja": "Lizardにおける側頭腺障害（イグアナ）の治療は血液異常の基礎原因の特定と対処が必要である。重度の貧血や急性出血には輸血が必要となりうる。凝固障害には新鮮凍結血漿、ビタミンK、または特定の凝固因子補充が必要な場合がある。免疫介在性破壊には免疫抑制療法が適応となる。酸素補充、輸液、栄養サポート、連続血液検査による血液学的パラメータのモニタリングを含む支持療法を行う。",
        "prevention": "骨髄炎（Lizard）の予防には適切な飼育管理、種に合ったバランスの取れた栄養、定期的な健康診断、ストレスの最小化、清潔な生活環境の維持、初期臨床徴候への迅速な対応が含まれる。",
        "prevention_ja": "側頭腺障害（イグアナ）の予防には全血球計算を含む定期的な健康モニタリング、既知のトリガー（毒素、感染性病原体）への曝露の最小化、適切なワクチン接種と寄生虫予防、血液学的副作用が知られる薬剤の回避、粘膜蒼白、点状出血、原因不明の無気力などの初期徴候に対する迅速な獣医学的対応が含まれる。",
        "prognosis": "",
        "prognosis_ja": "側頭腺障害（イグアナ）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"subacute", "chronic"},
        "age_predisposition": {"adult", "senior"},
    },
